<template>
  <div>
    <div class="page-intro"><div><h2>业务数据管理</h2><p>{{ scopeText }}；新增、修改、删除均由后端校验站点归属与关联约束</p></div><div class="filters"><span class="scope-chip">{{ auth.isGlobalAdmin?'ADMIN':'SITE_ADMIN' }}</span><el-select v-if="auth.isGlobalAdmin" v-model="selectedSite" style="width:145px" @change="scopeChanged"><el-option label="全部站点" :value="0"/><el-option v-for="id in [1,2,3]" :key="id" :label="'Site '+id" :value="id"/></el-select><el-button type="primary" @click="openCreate">新增{{ tabLabel }}</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div>
    <section class="panel"><el-tabs v-model="activeTab" class="resource-tabs" @tab-change="tabChanged">
      <el-tab-pane label="读者" name="readers"><el-table :data="rows" height="570"><el-table-column prop="data_site_id" label="站点" width="65"><template #default="s"><span class="site-tag">S{{ s.row.data_site_id }}</span></template></el-table-column><el-table-column prop="reader_id" label="读者 ID" width="125"/><el-table-column prop="reader_name" label="姓名" width="100"/><el-table-column prop="student_no" label="账号/学号" min-width="135"/><el-table-column prop="reader_type" label="类型" width="120"/><el-table-column prop="network_permission" label="跨校" width="70"><template #default="s">{{ s.row.network_permission?'允许':'禁止' }}</template></el-table-column><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="135" fixed="right"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">修改</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="馆藏副本" name="copies"><el-table :data="rows" height="570"><el-table-column prop="data_site_id" label="站点" width="65"><template #default="s"><span class="site-tag">S{{ s.row.data_site_id }}</span></template></el-table-column><el-table-column prop="copy_id" label="副本 ID" width="115"/><el-table-column prop="title" label="书名" min-width="180" show-overflow-tooltip/><el-table-column prop="barcode" label="条码" width="145"/><el-table-column prop="current_library_id" label="当前馆" width="90"/><el-table-column prop="shelf_location" label="架位" width="90"/><el-table-column prop="copy_status" label="状态" width="105"/><el-table-column label="操作" width="135" fixed="right"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">修改</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="借阅记录" name="borrow-records"><el-table :data="rows" height="570"><el-table-column prop="data_site_id" label="站点" width="65"><template #default="s"><span class="site-tag">S{{ s.row.data_site_id }}</span></template></el-table-column><el-table-column prop="borrow_id" label="借阅 ID" width="120"/><el-table-column prop="reader_id" label="读者 ID" width="125"/><el-table-column prop="copy_id" label="副本 ID" width="115"/><el-table-column prop="borrow_type" label="类型" width="135"/><el-table-column prop="borrow_status" label="状态" width="100"/><el-table-column prop="due_time" label="应还时间" min-width="165"><template #default="s">{{ formatDate(s.row.due_time) }}</template></el-table-column><el-table-column label="操作" width="135" fixed="right"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">修改</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="高校图书馆" name="libraries"><el-table :data="rows" height="570"><el-table-column prop="data_site_id" label="站点" width="65"><template #default="s"><span class="site-tag">S{{ s.row.data_site_id }}</span></template></el-table-column><el-table-column prop="library_id" label="馆 ID" width="85"/><el-table-column prop="library_name" label="图书馆" min-width="180"/><el-table-column prop="campus_id" label="校区 ID" width="90"/><el-table-column prop="address" label="地址" min-width="170" show-overflow-tooltip/><el-table-column label="坐标" width="150"><template #default="s">{{ s.row.longitude }}, {{ s.row.latitude }}</template></el-table-column><el-table-column prop="service_radius_m" label="服务范围(m)" width="105"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="135" fixed="right"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">修改</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
    </el-tabs><div class="row-count">当前范围共 {{ rows.length }} 条记录</div></section>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="section-gap"/>

    <el-dialog v-model="dialogVisible" :title="(editing?'修改':'新增')+tabLabel" width="min(760px,94vw)" destroy-on-close>
      <el-form label-position="top" class="edit-form">
        <el-form-item v-if="!editing&&auth.isGlobalAdmin" label="目标数据站点（必填）"><el-select v-model="form.site_id" @change="siteChanged"><el-option v-for="id in [1,2,3]" :key="id" :label="'Site '+id" :value="id"/></el-select></el-form-item>
        <template v-if="activeTab==='readers'">
          <el-form-item v-if="!editing" label="所属校区（决定高校和站点）"><el-select v-model="form.home_campus_id" filterable @change="readerCampusChanged"><el-option v-for="c in availableCampuses" :key="Number(c.campus_id)" :label="campusLabel(c)" :value="Number(c.campus_id)"/></el-select></el-form-item>
          <el-form-item v-if="!editing" label="学号（同时作为登录账号）"><el-input v-model="form.student_no"/></el-form-item><el-form-item v-if="!editing" label="校园一卡通号"><el-input v-model="form.network_card_no"/></el-form-item>
          <el-form-item label="姓名"><el-input v-model="form.reader_name"/></el-form-item><el-form-item label="手机"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item>
          <el-form-item label="读者类型"><el-select v-model="form.reader_type"><el-option v-for="v in readerTypes" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="最大借阅数"><el-input-number v-model="form.max_borrow_count" :min="0" :max="100"/></el-form-item><el-form-item label="允许跨校"><el-switch v-model="form.network_permission"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="v in readerStatuses" :key="v" :label="v" :value="v"/></el-select></el-form-item>
        </template>
        <template v-else-if="activeTab==='copies'">
          <el-form-item v-if="!editing" label="书目"><el-select v-model="form.book_id" filterable><el-option v-for="b in metadata.books" :key="Number(b.book_id)" :label="String(b.title)+' · '+String(b.isbn||'')" :value="Number(b.book_id)"/></el-select></el-form-item><el-form-item v-if="!editing" label="所属图书馆"><el-select v-model="form.owner_library_id" filterable @change="copyLibraryChanged"><el-option v-for="l in availableLibraries" :key="Number(l.library_id)" :label="String(l.library_name)" :value="Number(l.library_id)"/></el-select></el-form-item><el-form-item v-if="!editing" label="馆藏条码"><el-input v-model="form.barcode"/></el-form-item>
          <el-form-item label="当前图书馆"><el-select v-model="form.current_library_id" filterable><el-option v-for="l in availableLibraries" :key="Number(l.library_id)" :label="String(l.library_name)" :value="Number(l.library_id)"/></el-select></el-form-item><el-form-item label="架位"><el-input v-model="form.shelf_location"/></el-form-item><el-form-item label="馆藏状态"><el-select v-model="form.copy_status"><el-option v-for="v in copyStatuses" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="允许跨校借阅"><el-switch v-model="form.allow_cross_borrow"/></el-form-item><el-form-item label="入藏日期"><el-date-picker v-model="form.acquisition_date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="价格"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item>
        </template>
        <template v-else-if="activeTab==='borrow-records'">
          <el-form-item v-if="!editing" label="读者"><el-select v-model="form.reader_id" filterable @change="borrowReaderChanged"><el-option v-for="r in availableReaders" :key="Number(r.reader_id)" :label="String(r.reader_name)+' · '+r.reader_id" :value="Number(r.reader_id)"/></el-select></el-form-item><el-form-item v-if="!editing" label="馆藏副本"><el-select v-model="form.copy_id" filterable @change="borrowCopyChanged"><el-option v-for="c in availableCopies" :key="Number(c.copy_id)" :label="String(c.copy_id)+' · Book '+String(c.book_id)" :value="Number(c.copy_id)"/></el-select></el-form-item><el-form-item v-if="!editing" label="借出图书馆"><el-select v-model="form.checkout_library_id"><el-option v-for="l in availableLibraries" :key="Number(l.library_id)" :label="String(l.library_name)" :value="Number(l.library_id)"/></el-select></el-form-item><el-form-item v-if="!editing" label="借阅类型"><el-select v-model="form.borrow_type"><el-option v-for="v in borrowTypes" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item v-if="!editing" label="借出时间"><el-date-picker v-model="form.borrow_time" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item>
          <el-form-item label="应还时间"><el-date-picker v-model="form.due_time" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="归还图书馆"><el-select v-model="form.return_library_id" clearable><el-option v-for="l in availableLibraries" :key="Number(l.library_id)" :label="String(l.library_name)" :value="Number(l.library_id)"/></el-select></el-form-item><el-form-item label="归还时间"><el-date-picker v-model="form.return_time" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="状态"><el-select v-model="form.borrow_status"><el-option v-for="v in borrowStatuses" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="续借次数"><el-input-number v-model="form.renew_count" :min="0"/></el-form-item><el-form-item label="罚金"><el-input-number v-model="form.fine_amount" :min="0" :precision="2"/></el-form-item>
        </template>
        <template v-else>
          <el-form-item v-if="!editing" label="高校与校区（必填）"><el-select v-model="form.campus_id" filterable @change="libraryCampusChanged"><el-option v-for="c in availableCampuses" :key="Number(c.campus_id)" :label="campusLabel(c)" :value="Number(c.campus_id)"/></el-select></el-form-item><el-form-item label="图书馆名称"><el-input v-model="form.library_name"/></el-form-item><el-form-item label="详细地址"><el-input v-model="form.address"/></el-form-item><el-form-item label="经度（WGS84）"><el-input-number v-model="form.longitude" :precision="7" :step="0.001"/></el-form-item><el-form-item label="纬度（WGS84）"><el-input-number v-model="form.latitude" :precision="7" :step="0.001"/></el-form-item><el-form-item label="服务范围（米）"><el-input-number v-model="form.service_radius_m" :min="1" :max="100000"/></el-form-item><el-form-item label="开放时间"><el-time-picker v-model="form.open_time" value-format="HH:mm:ss"/></el-form-item><el-form-item label="闭馆时间"><el-time-picker v-model="form.close_time" value-format="HH:mm:ss"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="座位数"><el-input-number v-model="form.total_seats" :min="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="v in libraryStatuses" :key="v" :label="v" :value="v"/></el-select></el-form-item>
        </template>
      </el-form>
      <template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">保存</el-button></template>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { apiErrorMessage,createAdminResource,deleteAdminResource,getAdminMetadata,getAdminResources,updateAdminResource,type AdminResourceKind } from '@/api/client';import { useAuthStore } from '@/stores/auth';import type { DataRow } from '@/types'
const auth=useAuthStore(),activeTab=ref<AdminResourceKind>('readers'),selectedSite=ref(0),rows=ref<DataRow[]>([]),loading=ref(false),saving=ref(false),error=ref(''),dialogVisible=ref(false),editing=ref(false),editingId=ref(0),editingSite=ref(0),form=reactive<Record<string,any>>({}),metadata=reactive<Record<string,DataRow[]>>({universities:[],campuses:[],books:[],libraries:[],readers:[],copies:[]})
const readerTypes=['UNDERGRADUATE','POSTGRADUATE','TEACHER'],readerStatuses=['ACTIVE','FROZEN','DISABLED'],copyStatuses=['AVAILABLE','BORROWED','IN_TRANSIT','REPAIR','LOST'],borrowTypes=['LOCAL','CROSS_CAMPUS','CROSS_UNIVERSITY'],borrowStatuses=['BORROWING','RETURNED','OVERDUE','LOST'],libraryStatuses=['OPEN','CLOSED','MAINTENANCE'];const labels:Record<AdminResourceKind,string>={readers:'读者',copies:'馆藏副本','borrow-records':'借阅记录',libraries:'高校图书馆'};const tabLabel=computed(()=>labels[activeTab.value]),scopeText=computed(()=>auth.isGlobalAdmin?(selectedSite.value?'正在管理 Site '+selectedSite.value:'正在管理全部站点'):'仅管理 Site '+auth.user?.managed_site_id);const targetSite=computed(()=>editing.value?editingSite.value:Number(form.site_id||selectedSite.value||auth.user?.managed_site_id||1));const availableCampuses=computed(()=>metadata.campuses.filter(c=>Number(c.site_id)===targetSite.value)),availableLibraries=computed(()=>metadata.libraries.filter(l=>Number(l.data_site_id)===targetSite.value)),availableReaders=computed(()=>metadata.readers.filter(r=>Number(r.data_site_id)===targetSite.value)),availableCopies=computed(()=>metadata.copies.filter(c=>Number(c.data_site_id)===targetSite.value))
async function load(){loading.value=true;error.value='';try{rows.value=(await getAdminResources(activeTab.value,selectedSite.value||undefined)).rows;const m=await getAdminMetadata(selectedSite.value||undefined);Object.keys(metadata).forEach(k=>metadata[k]=(m[k] as DataRow[])||[])}catch(e){error.value=apiErrorMessage(e)}finally{loading.value=false}}function scopeChanged(){load()}function tabChanged(){load()}
function defaults(){const now=new Date(),due=new Date(now.getTime()+30*86400000);return activeTab.value==='readers'?{site_id:selectedSite.value||auth.user?.managed_site_id||1,reader_name:'',student_no:'',network_card_no:'',phone:'',email:'',reader_type:'UNDERGRADUATE',network_permission:true,max_borrow_count:10,status:'ACTIVE'}:activeTab.value==='copies'?{site_id:selectedSite.value||auth.user?.managed_site_id||1,barcode:'',shelf_location:'',copy_status:'AVAILABLE',allow_cross_borrow:true,price:0}:activeTab.value==='borrow-records'?{site_id:selectedSite.value||auth.user?.managed_site_id||1,borrow_type:'LOCAL',borrow_time:localDate(now),due_time:localDate(due),borrow_status:'BORROWING',renew_count:0,fine_amount:0}:{site_id:selectedSite.value||auth.user?.managed_site_id||1,library_name:'',address:'',longitude:104.066,latitude:30.67,service_radius_m:3000,open_time:'08:00:00',close_time:'22:00:00',phone:'',total_seats:0,status:'OPEN'}}
function resetForm(values:Record<string,unknown>){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,values)}function openCreate(){editing.value=false;editingId.value=0;resetForm(defaults());dialogVisible.value=true}function openEdit(row:DataRow){editing.value=true;editingSite.value=Number(row.data_site_id);editingId.value=Number(row[activeTab.value==='readers'?'reader_id':activeTab.value==='copies'?'copy_id':activeTab.value==='borrow-records'?'borrow_id':'library_id']);resetForm({...row,borrow_time:localDate(row.borrow_time),due_time:localDate(row.due_time),return_time:localDate(row.return_time)});dialogVisible.value=true}
function payload(){const p={...form};delete p.site_id;delete p.data_site_id;delete p.reader_id;delete p.copy_id;delete p.borrow_id;delete p.library_id;delete p.title;delete p.current_borrow_count;if(editing.value&&activeTab.value==='readers'){delete p.student_no;delete p.network_card_no;delete p.home_university_id;delete p.home_campus_id}if(editing.value&&activeTab.value==='copies'){delete p.book_id;delete p.owner_university_id;delete p.owner_campus_id;delete p.owner_library_id;delete p.barcode}if(editing.value&&activeTab.value==='borrow-records'){delete p.reader_id;delete p.reader_home_campus_id;delete p.book_id;delete p.copy_id;delete p.copy_owner_site_id;delete p.checkout_library_id;delete p.borrow_type;delete p.borrow_time}if(editing.value&&activeTab.value==='libraries'){delete p.university_id;delete p.campus_id}Object.keys(p).forEach(k=>(p[k]===null||p[k]==='')&&delete p[k]);return p}
async function submit(){if(!targetSite.value){ElMessage.warning('请选择目标站点');return}saving.value=true;try{if(editing.value)await updateAdminResource(activeTab.value,editingId.value,targetSite.value,payload());else await createAdminResource(activeTab.value,targetSite.value,payload());ElMessage.success((editing.value?'修改':'新增')+'成功');dialogVisible.value=false;await load()}catch(e){ElMessage.error(apiErrorMessage(e))}finally{saving.value=false}}
async function remove(row:DataRow){const id=Number(row[activeTab.value==='readers'?'reader_id':activeTab.value==='copies'?'copy_id':activeTab.value==='borrow-records'?'borrow_id':'library_id']);try{await ElMessageBox.confirm('删除后无法恢复；存在关联数据时后端会拒绝操作。','确认删除',{type:'warning'});await deleteAdminResource(activeTab.value,id,Number(row.data_site_id));ElMessage.success('删除成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e))}}
function siteChanged(){form.home_campus_id=undefined;form.owner_library_id=undefined;form.campus_id=undefined}function readerCampusChanged(id:number){const c=metadata.campuses.find(x=>Number(x.campus_id)===id);if(c)form.home_university_id=Number(c.university_id)}function libraryCampusChanged(id:number){const c=metadata.campuses.find(x=>Number(x.campus_id)===id);if(c){form.university_id=Number(c.university_id);form.longitude=Number(c.longitude);form.latitude=Number(c.latitude)}}function copyLibraryChanged(id:number){const l=metadata.libraries.find(x=>Number(x.library_id)===id);if(l){form.owner_university_id=Number(l.university_id);form.owner_campus_id=Number(l.campus_id);form.current_library_id=id}}function borrowReaderChanged(id:number){const r=metadata.readers.find(x=>Number(x.reader_id)===id);if(r)form.reader_home_campus_id=Number(r.home_campus_id)}function borrowCopyChanged(id:number){const c=metadata.copies.find(x=>Number(x.copy_id)===id);if(c){form.book_id=Number(c.book_id);form.copy_owner_site_id=Number(c.data_site_id);form.checkout_library_id=Number(c.owner_library_id)}}function campusLabel(c:DataRow){const u=metadata.universities.find(x=>Number(x.university_id)===Number(c.university_id));return String(u?.short_name||u?.university_name||c.university_id)+' · '+String(c.campus_name)}function localDate(v:unknown){if(!v)return undefined;const d=new Date(String(v));if(Number.isNaN(d.getTime()))return String(v);const z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,19)}function formatDate(v:unknown){return v?new Date(String(v)).toLocaleString('zh-CN'):'—'}onMounted(load)
</script>
<style scoped>
.filters{display:flex;align-items:center;gap:9px}.scope-chip,.site-tag{padding:4px 7px;border:1px solid rgba(41,216,199,.22);border-radius:4px;color:var(--cyan);background:rgba(41,216,199,.07);font:9px 'DM Mono'}.resource-tabs{padding:7px 17px 0}.row-count{text-align:right;padding:10px 16px;color:#607990;font:9px 'DM Mono';border-top:1px solid var(--line)}.edit-form{display:grid;grid-template-columns:1fr 1fr;gap:0 18px;max-height:62vh;overflow:auto;padding:2px 5px}.edit-form :deep(.el-form-item){margin-bottom:13px}.edit-form :deep(.el-select),.edit-form :deep(.el-date-editor),.edit-form :deep(.el-input-number){width:100%}@media(max-width:760px){.page-intro{flex-direction:column}.filters{width:100%;flex-wrap:wrap}.edit-form{grid-template-columns:1fr}}
</style>
